import math
import threading
from functools import wraps


def rate_limit(leak_rate, capacity, clock):
    """Limit func to leak_rate tokens per clock-second with burst capacity."""
    if not math.isfinite(leak_rate) or leak_rate < 0:
        raise ValueError("leak_rate must be finite and non-negative")
    if not math.isfinite(capacity) or capacity < 1:
        raise ValueError("capacity must be finite and at least 1")

    tokens = float(capacity)
    last_refill = None
    lock = threading.Lock()

    def decorator(func):
        @wraps(func)
        def limited(*args, **kwargs):
            nonlocal tokens, last_refill

            with lock:
                now = clock()
                if last_refill is None:
                    last_refill = now
                elif now > last_refill:
                    tokens = min(
                        float(capacity),
                        tokens + (now - last_refill) * leak_rate,
                    )
                    last_refill = now

                if tokens < 1:
                    return False
                tokens -= 1

            return func(*args, **kwargs)

        return limited

    return decorator
